using System.Windows.Controls;using SobhanNotificationHub.Data;namespace SobhanNotificationHub.UI;public partial class NotificationHistoryWindow:System.Windows.Window{public NotificationHistoryWindow(){InitializeComponent();Loaded+=async(s,e)=>await LoadAsync();}private async Task LoadAsync(){if(ModuleFilter.SelectedItem is not ComboBoxItem item)return;HistoryGrid.ItemsSource=await App.Services.Cache.HistoryAsync(item.Tag?.ToString(),UnreadOnly.IsChecked==true);}private async void Refresh_Click(object s,RoutedEventArgs e)=>await LoadAsync();private async void Filter_Changed(object s,RoutedEventArgs e){if(IsLoaded)await LoadAsync();}private async void Read_Click(object s,RoutedEventArgs e){if(HistoryGrid.SelectedItem is not CachedNotification n)return;await App.Services.Router.RouteAsync(n.Id,"mark_read",null,CancellationToken.None);await LoadAsync();}private async void Open_Click(object s,RoutedEventArgs e){if(HistoryGrid.SelectedItem is not CachedNotification n)return;await App.Services.Router.RouteAsync(n.Id,"open",null,CancellationToken.None);}}
